window.ANTZ_I18N = {"meta":{"lang":"lt","source":false,"reviewed":false,"translator":"machine (Claude)"},"ui":{"brand.title":"Antz įvedimo vadovas","brand.label":"Įvedimo vadovas","brand.home":"Antz Systems, pradžia","meta.description":"Trumpas, vaizdinis Antz platformos vadovas gyvūnų priežiūros komandoms.","nav.primary":"Pagrindinė","nav.menu":"Meniu","nav.modules":"Moduliai","nav.why":"Kodėl Antz","nav.start":"Pradžia","nav.faq":"DUK","nav.search":"Ieškoti vadove","nav.searchTip":"Paieška (Ctrl/Cmd + K)","footer.tagline":"Geri duomenys = geros įžvalgos = sveiki gyvūnai","footer.explore":"Naršyti","footer.talk":"Susisiekite su mumis","footer.rights":"© 2026 Antz Systems. Visos teisės saugomos.","lang.label":"Kalba","lang.note":"Šis puslapis išverstas mašininiu būdu ir laukia gimtakalbio peržiūros.","lang.english":"Žiūrėti anglų kalba","lang.dismiss":"Uždaryti","lang.inApp":"Programėlėje: {x}","hero.title":"Viena platforma visiems Jūsų prižiūrimiems gyvūnams","hero.sub":"Įrašai, kasdienės operacijos ir komandinis darbas visose Jūsų vietose. Raskite bet kurią Antz užduotį su tikrais ekranais.","hero.areas":"Darbo sritys: {n}","hero.devices":"Mobilioji ir žiniatinklio versija","search.label":"Ieškoti modulių ir funkcijų","search.cue":"Ieškoti: {x}","search.clear":"Išvalyti paiešką","search.short":"Įveskite bent dvi raides, kad ieškotumėte visuose moduliuose ir funkcijose.","search.top":"Geriausi rezultatai","search.none":"Pagal „{q}“ nieko nerasta. Pabandykite „gyvūnas“, „kiaušinis“ arba „ataskaita“.","start.label":"Pradėkite čia","kit.objective.eyebrow":"Pradėkite čia","kit.objective.more":"Skaityti tikslą","kit.objective.kicker":"Kodėl rengiame šiuos mokymus","kit.objective.photo":"Prižiūrėtojas šeria mažą gyvūną jo aptvare","kit.platform.eyebrow":"Platforma","kit.platform.more":"Sužinokite apie Antz","kit.platform.why":"Kodėl verta naudoti šią programėlę","kit.platform.photo":"Ranka laiko telefoną su Antz Systems programėle","kit.start.eyebrow":"Įvedimo eiga","kit.start.more":"Pradėti vadovą","kit.start.features":"Funkcijos","day.title":"Kaip atrodo Jūsų pirmoji diena su Antz","day.lede":"Keturi žingsniai nuo pirmojo prisijungimo iki kasdienio naudojimo.","day.1":"Prisijunkite prie savo darbo erdvės","day.2":"Susipažinkite su sąsaja","day.3":"Nustatykite pagrindinius duomenis","day.4":"Suteikite visiems tinkamą prieigą","day.4.desc":"Sukurkite Jūsų organizaciją atitinkančius vaidmenis ir įjunkite leidimus kiekvienam moduliui atskirai, kad kiekvienas matytų tai, ko reikia jo darbui.","modules.eyebrow":"Kas viduje","modules.title":"Naršykite modulius","modules.lede":"Palieskite bet kurią kortelę, kad atvertumėte jos vadovą su visomis funkcijomis ir ekranais.","modules.filter":"Filtruoti modulius pagal sritį","modules.all":"Visi","modules.count":"Moduliai: {n}","modules.features":"Funkcijos: {n}","spot.tag":"Išskirtinė darbo eiga","spot.link":"Išsamiau: {x}","cta.title":"Užstrigote ties užduotimi?","cta.text":"Šiame vadove kiekvienas modulis pateikiamas su funkcijomis ir tikrais ekranais. Tęskite nuo ten, kur baigėte, arba parašykite mums – padėsime.","cta.back":"Atgal į modulius","cta.or":"Turite klausimų? Rašykite {email}","faq.eyebrow":"DUK","faq.title":"Klausimai, kuriuos komandos užduoda pirmiausia","faq.q1":"Kas yra Antz?","faq.q2":"Ar ji veikia telefonuose ir kompiuteriuose?","faq.a2":"Taip. Mobilioji programėlė skirta darbui vietoje, pavyzdžiui, pastaboms, gydymui, perkėlimams ir kiaušinių įrašams. Žiniatinklio programa skirta darbui prie stalo, pavyzdžiui, ligoninės sistemai, inkubatorinės nustatymui, ataskaitoms ir vaistinės atsargoms. Atnaujinimai realiuoju laiku rodomi telefone, planšetėje ir kompiuteryje.","faq.q3":"Ar galime valdyti, kas ką mato?","faq.a3":"Taip. Prieiga grindžiama vaidmenimis. Sukuriate savo organizacijoje naudojamus vaidmenis, pavyzdžiui, zoologo, ir įjungiate leidimus kiekvienam moduliui atskirai.","faq.q4":"Turime daugiau nei vieną vietą. Ar tai veiks?","faq.a4":"Antz saugo visų vietų ir skyrių duomenis vienoje vietoje. Laikymas suskirstytas pagal vietą, sekciją ir aptvarą, o perkėlimai tarp vietų vyksta per patvirtinimą ir apsaugos išregistravimą.","faq.q5":"Kaip pradėti?","faq.a5":"Pradėkite nuo vadovo „Pradžia“, tada atverkite modulius, kuriuos naudoja Jūsų vaidmuo. Jei kas nors neaišku, rašykite hello@antz.systems.","pager.prev":"Ankstesnis","pager.next":"Kitas","pager.modules":"Naršykite modulius","pager.pages":"Ankstesnis ir kitas puslapis","pager.moduleNav":"Ankstesnis ir kitas modulis","mod.tabs":"Modulių sritys ir moduliai","mod.features":"Funkcijos","mod.hintClick":"Spustelėkite funkciją, kad atvertumėte jos ekraną","mod.hintTap":"Palieskite funkciją, kad atvertumėte jos ekraną","mod.soon":"Šio modulio ekranai netrukus","mod.zoom":"Palieskite ekraną, kad padidintumėte","win.prev":"Ankstesnė funkcija","win.next":"Kita funkcija","win.close":"Uždaryti","win.count":"Funkcija {i} iš {n}","win.soon":"Ekranas netrukus","gal.label":"Ekranai: {x}","gal.close":"Uždaryti galeriją","gal.screen":"Ekranas {i}","gal.hint":"Suimkite pirštais arba dukart palieskite, kad padidintumėte · Braukite, kad naršytumėte"},"tracks":{"records":{"label":"Įrašai ir komunikacija","desc":"Lengviausios ir dažniausiai naudojamos sritys: pastabos, pokalbiai ir naudotojų nustatymai."},"animal":{"label":"Gyvūnų įrašai ir judėjimas","desc":"Kolekcija, laikymas ir kiekvienas gyvūno judėjimas zoologijos sode."},"medical":{"label":"Medicina ir gydymas","desc":"Įrašai, receptai, gydymas ir ligoninės informacinė sistema."},"mortality":{"label":"Gaištamumas ir gyvavimo ciklas","desc":"Gaištamumas, skrodimai ir kiaušinių gyvavimo ciklo valdymas."},"operations":{"label":"Operacijos ir priežiūra","desc":"Skelbimai, pagalbos tarnyba, apsauga, ataskaitos ir atitiktis."}},"modules":{"objective-of-this-kit":{"title":"Šio rinkinio tikslas","intro":"Įvedimas turi keturis uždavinius: užtikrinti, kad kiekvienas komandos narys užtikrintai atliktų kasdienes užduotis, kad platforma būtų pritaikyta visiems vaidmenims, nustatyti spragas, kad galėtume tobulėti, ir suvienodinti įrašų tvarkymą visose vietose.","features":[{"title":"Įgūdžių ugdymas","desc":"Gilinkite darbuotojų žinias ir praktinius įgūdžius, reikalingus efektyviam zoologijos sodo darbui, gyvūnų priežiūrai ir užtikrintam Antz platformos naudojimui.","alt":""},{"title":"Sistemos pritaikymas","desc":"Supažindinkite naudotojus su kiekvienu programėlės moduliu ir ugdykite pasitikėjimą, kad pagrindinius veiksmus, tokius kaip įrašymas, peržiūra ir tvirtinimas, jie atliktų be priežiūros.","alt":""},{"title":"Nuolatinis tobulinimas","desc":"Nustatykite spragas, išsklaidykite abejones ir naudokite grįžtamuoju ryšiu grįstą mokymąsi, kad laikui bėgant tobulintumėte darbo eigas ir modulių veikimą.","alt":""},{"title":"Standartizavimas","desc":"Vienodi protokolai visose komandose ir vietose, vienodas užklausų, gaištamumo, kiaušinių ir mitybos modulių veikimas, kad kiekvienas įrašas būtų skaitomas vienodai.","alt":""}]},"what-is-antz-systems":{"title":"Kas yra Antz Systems?","intro":"Antz – tai visa apimanti platforma gyvūnų įrašams, kasdienėms operacijoms ir komandiniam darbui. Ji sutelkia visų vietų ir skyrių duomenis vienoje vietoje, todėl kiekvienas veiksmas yra dokumentuotas, skaidrus ir atsekamas.","features":[{"title":"Geresni įrašai – geresnė priežiūra","desc":"Kiekviena detalė tiksli, prieinama, pažymėta laiku ir susieta su tinkamu gyvūnu.","alt":""},{"title":"Paprastas komandinis darbas","desc":"Jokių spragų tarp veterinarų, prižiūrėtojų ir vadovų – visi dirba su tuo pačiu įrašu.","alt":""},{"title":"Saugi iš prigimties","desc":"Vaidmenimis grįsta prieiga apsaugo jautrius duomenis ir suderina teises su organizacine struktūra.","alt":""},{"title":"Sprendimai po ranka","desc":"Greitesnės ataskaitos ir atitikčiai paruoštos įžvalgos be skaičiuoklių.","alt":""},{"title":"Darbas be popieriaus","desc":"Mažiau perrašymo klaidų ir sutaupyto laiko kiekvienoje pamainoje.","alt":""},{"title":"Atnaujinimai realiuoju laiku","desc":"Naujausia informacija bet kada ir bet kur – telefone, planšetėje ir kompiuteryje.","alt":""}],"shots":{"assets/shots/app-welcome-c.jpg":"Antz Systems programėlės pasveikinimo ekranas: geri duomenys + geros įžvalgos = sveiki gyvūnai."}},"getting-started":{"title":"Pradžia","intro":"Vadovas „Pradžia“ pristato programėlės paskirtį ir supažindina naujus naudotojus su pagrindiniais žingsniais: kaip nustatyti profilį, susipažinti su pagrindinėmis funkcijomis ir efektyviai naršyti platformoje.","features":[{"title":"Prieiga ir darbo erdvės","desc":"Saugiai prisijunkite ir pasiekite Jums priskirtą darbo aplinką.","alt":"Antz Systems pradžios ekranas: paieškos juosta, laukiantys skyrimai (Pending Administration), šio mėnesio įžvalgos su gimstamumu ir gaištamumu bei skelbimo kortelė"},{"title":"Naršymas ir sąsaja","desc":"Naudokite pradžios srautą naujienoms, greitosios navigacijos nuorodas ir apatinį skydelį pagrindiniams įrankiams.","alt":""},{"title":"Laukiantys skrodimai / skyrimai / paskirstymai","desc":"Gyvūnai, laukiantys skrodimo, administracinių dokumentų ir tolesnio paskirstymo ar utilizavimo procedūrų prieš galutinį įrašų uždarymą.","alt":""},{"title":"Pagrindiniai nustatymai ir moduliai","desc":"Konfigūruokite pagrindinius duomenis ir susipažinkite su tokiais moduliais kaip medicininiai įrašai, laikymo vietos, kiaušiniai, mityba ir gyvūnų valdymas.","alt":""},{"title":"Personalizavimas","desc":"Tvarkykite pastabas, atnaujinkite profilį ir keiskite kalbos nuostatas.","alt":""},{"title":"Leidimai","desc":"Supraskite prieigos lygius, reikalingus saugiam darbui.","alt":""}]},"notes-module":{"title":"Pastabų modulis","intro":"Pastabų modulis sutelkia kasdienių naujienų, stebėjimų ir incidentų, susijusių su gyvūnais, aptvarais ir operacijomis, registravimą. Jis užtikrina struktūruotus, laiku pažymėtus įrašus, sklandų komandos koordinavimą, greitą paiešką pagal filtrus ir žymas bei padeda nuosekliai prižiūrėti gyvūnus, anksti pastebėti problemas ir laikytis reikalavimų.","summary":"Kasdienių naujienų, stebėjimų ir incidentų, susijusių su gyvūnais, aptvarais ir operacijomis, registravimas vienoje vietoje","features":[{"title":"Pastabų kūrimas ir peržiūra","desc":"Kurkite naujas pastabas ir peržiūrėkite savo bei kitų įgaliotų naudotojų pastabas.","alt":"Naujos pastabos forma: pastabos tipas, pastabos, pranešimas nariams, objektas, priedai, prioritetas"},{"title":"Redagavimas, klausymas ir šalinimas","desc":"Keiskite, klausykitės garso įrašo arba šalinkite pastabas pagal priskirtus leidimus.","alt":"Pastabos informacija: Medical, Sick, tigras AID 425990, su redagavimo ir žymėjimo mygtukais"},{"title":"Prioritetas","desc":"Nustatykite skubumo lygį, kad tinkami žmonės pastabą pamatytų pirmieji.","alt":"Pastabos informacija su prioriteto vėliavėle viršuje dešinėje"},{"title":"Pastabos tipas ir susiejimas","desc":"Priskirkite kategoriją, susiekite su gyvūnais, aptvarais ar sekcijomis ir pridėkite dokumentus.","alt":"Pastabos informacija su susieto gyvūno kortele, tigras AID 425990"},{"title":"Matomumas","desc":"Pastabos automatiškai rodomos atitinkamo gyvūno, vietos ar sekcijos puslapiuose.","alt":"Vietos puslapio skirtukas „Notes“: higienos pastaba, rodoma Central Reserve Kingdom"},{"title":"Pranešimai ir bendradarbiavimas","desc":"Praneškite pažymėtiems nariams; patiktukai ir komentarai padeda išlaikyti dėmesį.","alt":"Pastaba su patiktuku, pažymėtu nariu Dr. Cloomy Fernandes ir 1 komentaru"},{"title":"Filtrai ir paieška","desc":"Filtruokite pagal raktinius žodžius, žymas, autorių arba susietą objektą.","alt":"Pastabų sąrašas su skirtukais „My Notes“ / „All Notes“ ir filtrais"}]},"user-management":{"title":"Naudotojų valdymas","intro":"Naudotojų modulis leidžia saugiai ir centralizuotai valdyti paskyras, vaidmenis ir leidimus. Jis supaprastina naujų naudotojų įvedimą, užtikrina duomenų saugumą ir suderina prieigos teises su organizacijos vaidmenimis, kartu saugodamas išsamius veiklos žurnalus atskaitomybei.","summary":"Saugus, centralizuotas paskyrų, vaidmenų ir leidimų valdymas","features":[{"title":"Profilio kūrimas ir tvarkymas","desc":"Tvarkykite vardą, kontaktus, darbuotojo ID, gimimo datą ir kraujo grupę.","alt":"Naudotojo pridėjimo pagrindinės informacijos forma: vardas, naudotojo vardas, el. paštas, slaptažodis, mobilusis telefonas, darbuotojo ID"},{"title":"Vaidmenys ir leidimai","desc":"Priskirkite vaidmenis ir tvarkykite prieigos teises modulių lygiu.","alt":"Leidimų redagavimas: veterinarijos gydytojo vaidmuo su modulių prieigos žymimaisiais langeliais"},{"title":"Prieigos kontrolė","desc":"Ribokite pagal vietą ar sekciją, aktyvinkite paskyras, nustatykite automatinį atsijungimą.","alt":"Naudotojo profilis su meniu „Deactivate“, „Reset Password“, „Reset Passcode“"},{"title":"Prisijungimas ir atkūrimas","desc":"Saugus prisijungimas su vienkartinio kodo atkūrimu per SMS arba WhatsApp.","alt":"Slaptažodžio atkūrimo / pamiršto slaptažodžio ekranas su naudotojo vardo arba el. pašto lauku"},{"title":"Veiklos stebėjimas","desc":"Peržiūrėkite paskutinį prisijungimą, įrenginių informaciją ir išjunkite įrenginius.","alt":"Naudotojo profilio skirtukas „Journal“: veiklos žurnalas su paskutinio aktyvumo laiku"},{"title":"Papildoma informacija","desc":"Įrašykite išsilavinimą, darbo patirtį ir įkelkite asmens dokumentus.","alt":"Naudotojo profilio skirtukas „Id Proofs“: Aadhaar kortelė su priedu"}]},"collection":{"title":"Kolekcija","intro":"Kolekcijos modulis skirtas valdyti ir dokumentuoti visus institucijos gyvūnų kolekcijos aspektus. Tai pagrindinis centras rūšims registruoti, atskiriems gyvūnams sekti ir tikslioms taksonominėms istorijoms saugoti.","summary":"Visų institucijos gyvūnų kolekcijos aspektų valdymas ir dokumentavimas: rūšių registravimas, atskirų gyvūnų sekimas ir tiksli taksonominė istorija","features":[{"title":"Kolekcijos apžvalga","desc":"Taksonomija, populiacija pagal lytį, įsigijimų ir gimimų skaičiai, su paieška.","alt":"Kolekcijų apžvalga: rūšių ir populiacijos rodikliai, priėmimai ir gimimai bei taksonominės klasės su skaičiais"},{"title":"Rūšių valdymas","desc":"Skaičiai, morfos, medicina, mityba, gaištamumas ir skrodimų būsena.","alt":"Tigro rūšies informacija su populiacija, vietomis, sekcijomis ir aptvarais"},{"title":"Grupinis vertinimas","desc":"Grupinis duomenų įvedimas su nuoseklia navigacija ir filtrais.","alt":"Rūšies vertinimų sąrašas su kiekvieno gyvūno kūno būkle"}]},"housing":{"title":"Laikymo vietos","intro":"Laikymo vietų modulis tvarko gyvūnų buveines visose Jūsų vietose, sekcijose ir aptvaruose, todėl kiekvieno gyvūno vieta žinoma, o kiekvienas pakeitimas sekamas. Prieiga kiekviename lygyje suteikiama pagal leidimus.","summary":"Gyvūnų buveinių tvarkymas visose vietose, sekcijose ir aptvaruose, kad kiekvieno gyvūno vieta būtų žinoma, o kiekvienas pakeitimas sekamas","features":[{"title":"Vietų administravimas","desc":"Pridėkite ar redaguokite vietas su vaidmenimis grįstais leidimais saugiai ir struktūruotai prieigai.","alt":"Vietos informacija: Wildlife Zoological Park su rūšių, gyvūnų ir sekcijų skaičiais bei aptvarų sąrašu"},{"title":"Sekcijų administravimas","desc":"Pridėkite ar redaguokite zoologijos sodo sekcijas su leidimais grįsta kontrole saugiam administravimui.","alt":"Sekcijos informacija: Animal Kingdom su rūšių, gyvūnų ir aptvarų skaičiais bei aptvarų sąrašu"},{"title":"Aptvarų administravimas","desc":"Pridėkite ar redaguokite aptvarus ir stebėkite kiekvieną jų, kad efektyviai prižiūrėtumėte gyvūnus ir duomenis.","alt":"Aptvarų sąrašas: Gentle Giants, Herbivores, The Tiger Trail su gyvūnų skaičiais"}]},"animal-management":{"title":"Gyvūnų valdymas","intro":"Gyvūnų modulis sutelkia visus gyvūnų įrašus vienoje vietoje – aktyvius, perkeltus, dingusius ar ištrintus – su profiliais, įsigijimo darbo eigomis ir patogiu skirtukų išdėstymu.","summary":"Visi gyvūnų įrašai vienoje vietoje","features":[{"title":"Gyvūnų paieška","desc":"Pridėkite naujus gyvūnus per nurodomas darbo eigas, susietas su laikymo vietomis, mityba ir medicina.","alt":"Gyvūnų sąrašas su skaičiais: visi gyvūnai 2828, perkelti 11, ištrinti 27, dingę / pabėgę 8"},{"title":"Neseniai pridėti","desc":"Naujai į sistemą įtraukti gyvūnai, srauto viršuje.","alt":"Neseniai pridėtų sąrašas: lėtasis loris, afrikinis savanų dramblys, tigras, sūriavandenis krokodilas, šalmuotasis kazuaras"},{"title":"Visi gyvūnai","desc":"Visa duomenų bazė, kurioje galima ieškoti, filtruoti ir eksportuoti.","alt":"Visų gyvūnų sąrašas: europinis triušis, šalmuotasis kazuaras, paprastasis hipopotamas, tigras, azijinis dramblys"},{"title":"Perkelti","desc":"Gyvūnai, perkelti tarp vietų ar aptvarų, su visa kilmės istorija.","alt":"Perkeltų gyvūnų sąrašas: tigras, liūtas, lėtasis loris, baribalas, liūtas"},{"title":"Ištrinti","desc":"Pašalintų gyvūnų įrašai, saugomi auditui ir galimam atkūrimui.","alt":"Ištrintų gyvūnų sąrašas"},{"title":"Dingę / pabėgę","desc":"Gyvūnai, pažymėti kaip dingę ar pabėgę, susieti su incidento ataskaita.","alt":"Dingusių / pabėgusių gyvūnų sąrašas: baribalas, šalmuotasis kazuaras, sūriavandenis krokodilas, paprastasis hipopotamas, tigras"}]},"tags-hub":{"title":"Žymų centras","intro":"Žymų centro modulis padeda tvarkyti ir skirstyti į kategorijas įvairius ANTZ platformos objektus (vietas, sekcijas, aptvarus, gyvūnus) naudojant pritaikomas etiketes pagal jų dabartinę būseną, paskirtį ar bet kokią pasirinktinę klasifikaciją.","summary":"Objektų (vietų, sekcijų, aptvarų, gyvūnų) tvarkymas ir skirstymas pritaikomomis etiketėmis pagal būseną, paskirtį ar pasirinktinę klasifikaciją","features":[{"title":"Žymų tipai – viešosios, privačios, sisteminės","desc":"Tvarkykite ir skirstykite objektus naudodami viešąsias, privačias ir sistemos apibrėžtas žymas.","alt":"„My Tags Hub“: paieška, bendras, sisteminių, viešųjų ir privačių žymų skaičius bei viešųjų ir privačių žymų lustai"},{"title":"Paieška ir filtrai","desc":"Greitai raskite žymas naudodami paiešką ir filtrus.","alt":"„My Tags Hub“: paieška, bendras, sisteminių, viešųjų ir privačių žymų skaičius bei viešųjų ir privačių žymų lustai"},{"title":"Žymų kūrimas","desc":"Kurkite naujas viešąsias ar privačias žymas pagal savo poreikius.","alt":"Naujos žymos kūrimas: žymos pavadinimas, kategorija, vaidmenys, kuriems pranešti, pastabos ir mygtukas „Create Tag“"},{"title":"Žymų redagavimas ir šalinimas","desc":"Keiskite privačių žymų pavadinimą, spalvą ar matomumą arba visam laikui pašalinkite nebereikalingas žymas.","alt":"Žymos informacijos lapas: kategorija, tipas, autorius, pastabos, pažymėti objektai, su veiksmais „Edit“ ir „Delete“"},{"title":"Viešųjų ir privačių žymų priskyrimas","desc":"Priskirkite žymas vietoms, sekcijoms, aptvarams ar gyvūnams, kad būtų patogu tvarkyti.","alt":"Gyvūno profilio skirtukas Žymos: viešos ir privačios žymos, Mano žymos ir Kitų žymos bei mygtukas + žymai pridėti"},{"title":"Priskirtų žymų šalinimas","desc":"Prireikus pašalinkite žymas iš vietų, sekcijų, aptvarų ar gyvūnų.","alt":"Žymos šalinimo patvirtinimas: ar tikrai norite pašalinti šias žymas iš šios vietos? „Cancel“ arba „Remove“"},{"title":"Matomumas","desc":"Nustatykite, ar privačios žymos lieka asmeninės, ar matomos visiems naudotojams.","alt":"Privačios žymos informacija: žymos tipas „Private (Visible to All)“ su jungikliu „Make this tag visible to all“"},{"title":"Pažymėti objektai","desc":"Peržiūrėkite visas su pasirinkta žyma susietas vietas, sekcijas, aptvarus, rūšis ir gyvūnus.","alt":"Žymos „Laikas dehelmintizuoti“ skirtukas Objektai: 12 pažymėtų objektų, ieškomas aptvarų, skyrių, rūšių ir gyvūnų sąrašas"}]},"animal-transfer":{"title":"Gyvūnų perkėlimas","intro":"Registruoja ir valdo visus gyvūnų judėjimus organizacijos viduje ir už jos ribų, sekdamas užklausas, patvirtinimus ir paskirstymus, kad perkėlimas būtų saugus ir gerai dokumentuotas.","summary":"Visų gyvūnų judėjimų organizacijos viduje ir už jos ribų registravimas ir valdymas","features":[{"title":"Perkėlimo tipai","desc":"Vidiniai, tarp vietų ir išoriniai perkėlimai.","alt":"Perkėlimo tipo pasirinkimo langas: vidinis, tarp vietų ir išorinis"},{"title":"Patvirtinimas","desc":"Paskirtų vietos atsakingų asmenų leidimas.","alt":"Perkėlimas tarp vietų laukia patvirtinimo, su mygtukais Patvirtinti ir Atmesti"},{"title":"Atšaukimas / atmetimas","desc":"Atšaukite ar atmeskite užklausas ir prireikus inicijuokite iš naujo.","alt":"Perkėlimo meniu parinktis Atšaukti perkėlimą"},{"title":"Apsaugos įregistravimas / išregistravimas","desc":"Kontroliuojamas įregistravimas ir išregistravimas perkeliant tarp vietų ir už organizacijos ribų.","alt":"Laukiama apsaugos patikra su veiksmu Apsaugos išvykimas"},{"title":"Paskirstymas","desc":"Atvykus paskirkite į aptvarą ir praneškite darbuotojams.","alt":"Būsena Gyvūnai gauti su veiksmu Priskirti aptvarus"},{"title":"Perkėlimų žurnalas","desc":"Visa būsenų istorija su laiko žymomis ir naudotojais.","alt":"Perkėlimo laiko juosta, kuri baigiasi būsena Perkėlimas baigtas"}]},"approvals":{"title":"Patvirtinimai","intro":"Valdo ir seka gyvūnų perkėlimo užklausas, rodydamas laukiančias, patvirtintas ir atmestas užklausas. Jis supaprastina peržiūros procesą, užtikrina tinkamą leidimą ir saugo skaidrų perkėlimo sprendimų įrašą atskaitomybei ir atitikčiai.","summary":"Gyvūnų perkėlimo užklausų valdymas ir sekimas: laukiančios, patvirtintos ir atmestos užklausos","features":[{"title":"Būsenos sekimas","desc":"Laukia patvirtinimo, patvirtinta, atmesta, leisti išvykti / atvykti, paskirstyta.","alt":"Perkėlimų patvirtinimų sąrašas su būsenos ženkliukais"},{"title":"Užklausos peržiūra","desc":"Prieš tvirtindami peržiūrėkite visą informaciją.","alt":"Perkėlimo užklausos informacija peržiūrai"},{"title":"Tvirtinimas / atmetimas","desc":"Patvirtinkite arba atmeskite su tinkamu pagrindimu.","alt":"Perkėlimo užklausos informacija su „Approve“ ir „Reject“"},{"title":"Patvirtinimo atstatymas","desc":"Iš naujo atverkite ar atnaujinkite anksčiau patvirtintą užklausą.","alt":"Patvirtintas perkėlimas su parinktimi „Reset Approval“"},{"title":"Perkėlimo atšaukimas","desc":"Atšaukite prieš patvirtinimą ar po jo, užregistruodami priežastį.","alt":"Užklausos informacija su parinktimi „Cancel Transfer“"}]},"missing-escaped-animal":{"title":"Dingęs / pabėgęs gyvūnas","intro":"Leidžia greitai pranešti apie dingusius ar pabėgusius gyvūnus, sekti ir išspręsti tokius atvejus. Laiku pažymėti įrašai susiejami su gyvūnų profiliais atskaitomybei ir koordinuotam apsaugos, veterinarų ir vadovybės veiksmų atsakui.","summary":"Greitas pranešimas apie dingusius ar pabėgusius gyvūnus, jų sekimas ir atvejų išsprendimas","features":[{"title":"Pranešimas apie incidentą ir priedai","desc":"Užregistruokite informaciją, veiksmus ir įkelkite nuotraukas ar vaizdo įrašus.","alt":"Pranešimo apie pabėgusius / dingusius gyvūnus forma"},{"title":"Ataskaitos redagavimas","desc":"Atnaujinkite ar keiskite incidento ataskaitą, kai situacija keičiasi.","alt":"Incidento laiko juosta, gyvūnas dingęs"},{"title":"Pranešimas apie suradimą","desc":"Įrašykite suradimo informaciją ir pažymėkite pataisymus.","alt":"Pranešimo apie rastą gyvūną forma"},{"title":"Įvykių registravimas ir atsekamumas","desc":"Kiekvienas veiksmas iš eilės įrašomas gyvūno laiko juostoje.","alt":"Meniu parinktis „Misreport missing“"},{"title":"Matomumas","desc":"Gyvūno profilyje pažymėta kaip dingęs.","alt":"Gyvūno profilis su dingusio ženkliuku ir QR kodu"}]},"medical-records":{"title":"Medicininiai įrašai","intro":"Medicinos modulis padeda įrašyti, sekti ir tvarkyti gyvūnų sveikatos duomenis, įskaitant diagnozes, receptus ir gydymą. Jis padeda laiku suteikti priežiūrą, tvarkingai kaupti ligos istorijas ir koordinuoti veterinarų komandų darbą, kad gyvūnų gerovė būtų geresnė.","summary":"Gyvūnų sveikatos duomenų įrašymas, sekimas ir tvarkymas","features":[{"title":"Įrašų kūrimas","desc":"Kelios darbo eigos pavieniams, partijos, grupės, suplanuotiems (vakcinacija, dehelmintizacija, papildai) arba tiesioginiams (skyrimas, receptas, vakcinacija, dehelmintizacija, papildai) įrašams ir laboratorinių tyrimų užklausoms pridėti, su tikslia data ir laiku.","alt":"Įrašų kūrimo meniu: pavienis, grupės, partijos medicininis įrašas, jungtinė laboratorinė užklausa, tiesioginis skyrimas, receptas, vakcinacija, dehelmintizacija, papildai"},{"title":"Įrašo apžvalga","desc":"Trumpa suvestinė su gydytojo informacija ir gyvūno profiliu, patogi greitai peržiūrai.","alt":"Medicininio įrašo MED-09501 apžvalga: gydytojas, gyvūno profilis, atvejo tipas ir simptomai"},{"title":"Žymėjimas, redagavimas, šalinimas, atsisiuntimas","desc":"Keiskite ar šalinkite įrašus; atsisiųstos ataskaitos siunčiamos registruotu el. pašto adresu.","alt":"Medicininis įrašas MED-08805 su žymėjimo, redagavimo ir papildomų parinkčių piktogramomis"},{"title":"Medicininio žurnalo laiko juosta","desc":"Chronologinis visų pridėjimo ir redagavimo veiksmų žurnalas su visišku atsekamumu.","alt":"Medicininis žurnalas: chronologinis medicininių įrašų veiksmų žurnalas su laiko žymomis"},{"title":"Įrašų perskyrimas","desc":"Gydytojai gali perskirti sau įrašus, kuriuos iš pradžių sukūrė kitas veterinaras.","alt":"Perskyrimo patvirtinimas: ar norite perskirti šį medicininį įrašą sau? Taip / Ne"}]},"symptoms-clinical-assessment-prescription":{"title":"Simptomai, klinikinis vertinimas ir receptai","intro":"Simptomų, klinikinio vertinimo ir receptų funkcija pateikia įžvalgas apie užregistruotus simptomus, diagnozes ir paskirtą gydymą, padėdama naudotojams stebėti sveikatos tendencijas ir priimti pagrįstus klinikinius sprendimus.","summary":"Įžvalgos apie užregistruotus simptomus, diagnozes ir paskirtą gydymą sveikatos tendencijoms stebėti ir klinikiniams sprendimams pagrįsti","features":[{"title":"Simptomų tendencijos","desc":"Analizuokite dažniausiai registruojamus simptomus įvairiose rūšyse ir sekite simptomų pasireiškimą laikui bėgant.","alt":"Simptomų analitika: 7 rūšys, 7 pagal simptomus, reitingas, kuriame pirmauja nenormalios išmatos, nenormali laikysena, nenormalus šėrimasis"},{"title":"Klinikinio vertinimo įžvalgos","desc":"Stebėkite gyvūnams atliktus klinikinius vertinimus ir nustatykite dažniausiai registruojamas diagnozes ar būkles.","alt":"Klinikinio vertinimo analitika: 20 rūšių, 35 vertinimai, pirmauja kepenų ligos, dantų ėduonis, virškinimo trakto sutrikimai"},{"title":"Receptų analitika","desc":"Peržiūrėkite dažniausiai skiriamus vaistus ir gydymo modelius pagal rūšis ir atvejus.","alt":"Receptų analitika: 7 rūšys, 7 receptai, pirmauja Aculife, Fluvac Innovator, Dolo 650"},{"title":"Filtrai ir paieška","desc":"Tikslinkite duomenis pagal laikotarpį, vietą, rūšį ir kitus kriterijus.","alt":"Filtravimas pagal laikotarpį: šiandien, vakar, paskutinės 7 dienos, šis mėnuo, paskutiniai 3 mėnesiai, paskutiniai 6 mėnesiai, visi duomenys"}]},"administer-medicine":{"title":"Vaistų skyrimas","intro":"Skyrimo modulis papildo medicininius įrašus, paversdamas receptus konkrečiomis gydymo darbo eigomis. Jis leidžia realiuoju laiku gydyti pavienius gyvūnus ar jų partijas – lauke ar ligoninėje.","summary":"Papildo medicininius įrašus, paversdamas receptus konkrečiomis gydymo darbo eigomis","features":[{"title":"Greitas įvedimas","desc":"Sukurkite tiesioginio skyrimo įrašą pasirinktai datai nerašydami viso medicininio įrašo.","alt":"Skyrimo ekranas: datų juosta, skirtukai „Animal“ / „Group Records“, būsenų plytelės „Administered“ / „Skipped“ / „Stopped“ / „Pending“, paryškintas greitojo įvedimo pliuso mygtukas"},{"title":"Paieška ir filtrai","desc":"Greitai raskite įrašus ir susiaurinkite sąrašą pagal datą, objektą, rūšį ar kontroliuojamąją medžiagą.","alt":"Skyrimo ekranas su paryškinta paieška, filtrais, mėnesio parinkikliu ir išskleidžiamuoju sąrašu „All Records“"},{"title":"Būsenos sekimas","desc":"Peržiūrėkite gydymą pagal datą keturiuose skirtukuose: laukiantys, skirti, praleisti, nutraukti.","alt":"Skyrimo ekranas su paryškintais būsenų skirtukais „Administered“, „Skipped“, „Stopped“, „Pending“"},{"title":"Masiniai veiksmai","desc":"Pasirinkite kelis įrašus ir vienu kartu pažymėkite vaistus kaip skirtus („Administer“) arba praleistus („Skip“).","alt":"Skyrimo ekranas su paryškintu „Select all“ ir mygtuku „Administer“ pasirinkus įrašus"},{"title":"Recepto informacija","desc":"Visa informacija – dozė, serijos numeris, susietas gyvūnas – matoma skyrimo metu.","alt":"Recepto ekranas su paryškintais laikais, dažnumu, trukme ir vartojimo būdu"},{"title":"Pavienės dozės įvedimas","desc":"Įrašykite atskiras dozes su laiku, serijos numeriu ir pastabomis.","alt":"Skyrimo ekranas su paryškinta pavienės dozės grupės kortele ir jos žymimuoju langeliu"},{"title":"Pradžios ekrano apžvalga","desc":"Laukiančių gydymo procedūrų skaičius rodomas tiesiog pradžios ekrane, kad galėtumėte greičiau imtis veiksmų.","alt":"Ekranas Laukiami skyrimai: iš viso 847 laukiančios dozės pagal gyvūnus, vaistus ir kontroliuojamas medžiagas, suskirstytos pagal vietą"}],"shots":{"assets/shots/p20-bulk.png":"Masiniai skyrimo veiksmai: „Select all“, pasirinktas gyvūno įrašas ir mygtukai „Skipped“ / „Administer“","assets/shots/p20-prescription.png":"Recepto informacija: atvejo ID, laikai, dažnumas, trukmė, vartojimo būdas, susietas gyvūnas ir dozavimo grafikas"}},"vaccination":{"title":"Vakcinacija","intro":"Vakcinacijos modulis valdo visą gyvūnų vakcinacijos ciklą – nuo planavimo ir tiesioginio skyrimo iki būsimų, laukiančių, praleistų ir atliktų vakcinacijų sekimo. Jis užtikrina savalaikį gydymą, tikslų dozių registravimą ir visišką atsekamumą ligų prevencijai ir klinikinei atitikčiai.","summary":"Viso gyvūnų vakcinacijos ciklo valdymas – nuo planavimo ir tiesioginio skyrimo iki būsimų, laukiančių, praleistų ir atliktų vakcinacijų sekimo","features":[{"title":"Rodiniai pagal būseną","desc":"Vakcinacijos suskirstytos į būsimas, laukiančias, praleistas, atliktas ir sustabdytas, kad būtų lengva stebėti.","alt":"Vakcinacijos meniu: „Upcoming“, „Pending“, „Completed“, „Skipped“, „Stopped Vaccine“, „Direct Administer“, „Schedule Vaccination“"},{"title":"Vakcinacijos valdymas","desc":"Suplanuokite vakcinaciją arba tiesiogiai įrašykite suleistą vakciną su nustatytomis datomis ir vaisto informacija.","alt":"Vakcinacijos planavimas su pasirinktais gyvūnais, receptu ir klinikinėmis pastabomis"},{"title":"Skyrimo registravimas","desc":"Fiksuojama dozė, serijos numeris, vartojimo būdas, pastabos ir pasirinktinai – pakartotinė apžiūra.","alt":"Atliktos vakcinacijos informacija su atvejo ID ir serijos numeriu"},{"title":"Laukiančios ir būsimos","desc":"Rodomos visos suplanuotos vakcinacijos pagal datą ir vietą, kad nė viena nebūtų praleista.","alt":"Laukiančios vakcinacijos, sugrupuotos pagal rūšis"},{"title":"Praleidimas ir nutraukimas","desc":"Atidėkite ar nutraukite vakcinacijas nurodydami privalomą priežastį ir pakartotinės apžiūros datą.","alt":"Laukiančios vakcinacijos informacija su veiksmais „Administer“ ir „Skipped“"},{"title":"Prieiga per gyvūną","desc":"Vakcinacijos įrašus galima peržiūrėti per gyvūnų, laikymo vietų ar medicininių įrašų skiltis.","alt":"Gyvūno profilio skirtukas „Medical“ su laukiančiomis, būsimomis ir atliktomis vakcinacijomis"}]},"deworming":{"title":"Dehelmintizacija","intro":"Dehelmintizacijos modulis padeda sistemingai registruoti ir stebėti antiparazitinį gydymą, užtikrindamas savalaikį skyrimą, tinkamą dokumentavimą ir aiškų kiekvieno gyvūno kiekvienos dehelmintizacijos sekimą.","summary":"Sistemingas antiparazitinio gydymo registravimas ir stebėjimas","features":[{"title":"Rodiniai pagal būseną","desc":"Dehelmintizacijos suskirstytos į būsimas, laukiančias, praleistas, atliktas ir sustabdytas, kad būtų lengva stebėti.","alt":"Dehelmintizacijos meniu: „Upcoming“, „Pending“, „Completed“, „Skipped“, „Stopped Deworming“, „Direct Administer“, „Schedule Deworming“"},{"title":"Dehelmintizacijos valdymas","desc":"Suplanuokite kursą arba tiesiogiai įrašykite skirtą vaistą su nustatytomis datomis ir informacija.","alt":"Tiesioginė dehelmintizacija su pasirinktu gyvūnu, receptu ir klinikinėmis pastabomis"},{"title":"Skyrimo registravimas","desc":"Fiksuojama dozė, serijos numeris, vartojimo būdas, pastabos ir pasirinktinai – pakartotinė apžiūra.","alt":"Vaisto pridėjimas: dozės tipas, dozės kiekis, vartojimo būdas, pakartotinė apžiūra ir serijos numeris"},{"title":"Laukiančios ir būsimos","desc":"Peržiūrėkite visas suplanuotas dehelmintizacijas pagal datą ir vietą, kad nė viena nebūtų praleista.","alt":"Laukiančios dehelmintizacijos, sugrupuotos pagal rūšis"},{"title":"Praleidimas ir nutraukimas","desc":"Atidėkite ar nutraukite nurodydami privalomą priežastį ir pakartotinės apžiūros datą.","alt":"Dehelmintizacijos praleidimas: perplanuokite arba nutraukite nurodydami priežastį ir atsakydami į klausimą apie nepageidaujamą poveikį"},{"title":"Prieiga per gyvūną","desc":"Galima peržiūrėti per gyvūnų, laikymo vietų ar medicininių įrašų skiltis.","alt":"Gyvūno profilio skirtukas „Medical“ su laukiančiomis, būsimomis ir atliktomis dehelmintizacijomis"}]},"supplements":{"title":"Papildai","intro":"Papildų modulis padeda sistemingai registruoti ir stebėti maisto ir mitybos papildų programas, užtikrindamas savalaikį skyrimą, tinkamą dokumentavimą ir aiškų kiekvieno gyvūnui duoto papildo sekimą.","summary":"Sistemingas maisto ir mitybos papildų programų registravimas ir stebėjimas","features":[{"title":"Rodiniai pagal būseną","desc":"Papildai suskirstyti į būsimus, laukiančius, praleistus, atliktus ir sustabdytus, kad būtų lengva stebėti.","alt":"Papildų meniu: „Upcoming“, „Pending“, „Completed“, „Skipped“, „Stopped Supplements“, „Direct Administer“, „Schedule Supplements“"},{"title":"Papildų valdymas","desc":"Suplanuokite arba tiesiogiai įrašykite skirtus papildus su nustatytomis datomis ir informacija.","alt":"Tiesioginis papildų skyrimas su pasirinktu gyvūnu, receptu ir klinikinėmis pastabomis"},{"title":"Skyrimo registravimas","desc":"Fiksuojama dozė, serijos numeris, vartojimo būdas, pastabos ir pasirinktinai – pakartotinė apžiūra.","alt":"Papildų pridėjimas: dozės tipas, dozės kiekis, vartojimo būdas, pakartotinė apžiūra ir serijos numeris"},{"title":"Laukiantys ir būsimi","desc":"Visi suplanuoti papildai pagal datą ir vietą, kad nė vienas skyrimas nebūtų praleistas.","alt":"Laukiantys papildai, sugrupuoti pagal rūšis"},{"title":"Praleidimas ir nutraukimas","desc":"Atidėkite ar nutraukite nurodydami privalomą priežastį ir pakartotinės apžiūros datą.","alt":"Papildų praleidimas: perplanuokite arba nutraukite nurodydami priežastį ir pakartotinės apžiūros datą"},{"title":"Prieiga per gyvūną","desc":"Įrašus galima peržiūrėti per gyvūnų, laikymo vietų ar medicininių įrašų skiltis.","alt":"Gyvūno profilio skirtukas „Medical“ su laukiančiais, būsimais ir atliktais papildais"}]},"hospital-information-management-system-app":{"title":"Ligoninės informacijos valdymo sistema (App)","intro":"Programėlėje darbuotojai inicijuoja gyvūnų perkėlimą į ligoninę ir saugiai perveža pacientus, nurodydami medicininį ID, vizito tipą, tikslą, priedus, o vietoje ir ligoninėje atliekamas apsaugos įregistravimas ir išregistravimas.","summary":"Darbuotojai inicijuoja gyvūnų perkėlimą į ligoninę ir saugiai perveža pacientus","features":[{"title":"Perkėlimo užklausos","desc":"Teikite prašymus hospitalizuoti gyvūnus iš vietos į ligoninę su medicininiu ID, vizito tipu, tikslu ir priedais.","alt":"Gyvūno hospitalizavimo forma: pasirinktas gyvūnas, medicininis ID (sukurti naują), ligoninės ir vizito tipo laukai, „Submit“"},{"title":"Perkėlimo būsena","desc":"Sekite kiekvieną perkėlimą per jo etapus vietos lygiu: laukia, vežamas, priimtas, atšauktas ir atmestas.","alt":"Vietos profilio skirtukas Perkėlimas į ligoninę: skirtukai Kelyje, Priimti ir Atšaukti, su prašymais, pvz., HT29-00069, laukiančiais priėmimo"},{"title":"Apsaugos įregistravimas / išregistravimas","desc":"Kontroliuojamas pacientų judėjimas su apsaugos įregistravimu ir išregistravimu vietoje ir ligoninėje.","alt":"Perkėlimas HT29-00068: laukiama apsaugos išvykimo, su mygtuku Apsaugos atvykimas"},{"title":"Išrašymo ataskaitų peržiūra","desc":"Išrašymo santraukas ir hospitalizavimo istoriją pasiekite tiesiai programėlėje.","alt":"Jūrinio krokodilo medicininis įrašas MED29-18889: atvejo tipas ir veterinaro pridėtas priedas Discharge_Summary.pdf"}]},"hospital-information-management-system-web":{"title":"Ligoninės informacijos valdymo sistema (Web)","intro":"Žiniatinklio konsolėje klinikinės komandos priima ir rūšiuoja atvykstančius pacientus, stebi stacionaro ir ambulatorinius pacientus, įrašo gydymą ir išrašo gyvūnus – su visišku medicininiu atsekamumu ir atsisiunčiamomis ataskaitomis.","summary":"Klinikinės komandos priima ir rūšiuoja atvykstančius pacientus, stebi stacionaro ir ambulatorinius pacientus, įrašo gydymą ir išrašo gyvūnus","features":[{"title":"Priėmimas ir rūšiavimas","desc":"Priimkite arba atmeskite gyvūnų atvejus, paskirdami gydytoją, palatą ir gultą pagal gydymo poreikius.","alt":"Paciento priėmimo forma: pasirinktas gyvūnas, vizito tikslas, gydymo tipas „OPD“ / „Inpatient“, sveikatos būklė, „Reject“ ir „Admit“"},{"title":"Stacionaro / ambulatorinių pacientų stebėsena","desc":"Konfigūruokite ir įrašykite suplanuotus gyvybinius rodiklius ir stebėjimus su redaguojamomis laiko juostomis.","alt":"Atvykstančių pacientų sąrašas: skirtukai „Pending“ ir „Rejected“ su gyvūnais ir vizito tikslu"},{"title":"Klinikiniai ir gydymo įrašai","desc":"Simptomai, klinikinės pastabos, receptai, anestezija, chirurgija ir kitas gydymas – vienoje vietoje.","alt":"Stacionaro įrašas MED29-17409: priėmimo informacija ir skirtukai „Symptoms“ / „Clinical Assessment“ / „Prescription“"},{"title":"Išrašymas","desc":"Grąžinkite gyvūnus į aptvarą arba užregistruokite gaišimą su skrodimo užklausa ir priedais.","alt":"Išrašymo skirtukas: priėmimo priežastis, išrašymo tipas „Mortality“ / „Transfer to Enclosure“, „Discharge Animal“"},{"title":"Atsisiunčiamos ataskaitos","desc":"Išrašymo santraukos, dabartinio hospitalizavimo informacija ir ankstesnių vizitų istorija.","alt":"Išrašytų pacientų sąrašas su trukme, vizito tipu, vyriausiuoju veterinarijos gydytoju ir atsisiuntimo veiksmu"}]},"mortality":{"title":"Gaištamumas","intro":"Gaištamumo modulis leidžia greitai ir tiksliai registruoti gyvūnų gaišimą, tvarkyti skrodimo informaciją ir saugoti įrodymus vienoje vietoje. Jis didina skaidrumą, spartina sprendimų priėmimą, užtikrina atitiktį ir padeda geriau stebėti gyvūnų gerovę.","summary":"Greitas ir tikslus gyvūnų gaišimo registravimas, skrodimo informacijos tvarkymas ir įrodymų saugojimas vienoje vietoje","features":[{"title":"Gaištamumo suvestinė","desc":"Bendri gaišimų, paveiktų rūšių ir priežasčių skaičiai.","alt":"Mirtingumo suvestinė: 49 gyvūnai, 16 rūšių ir 6 priežastys, su paryškintais skaičiais"},{"title":"Sąrašai keliais rodiniais","desc":"Įrašai pagal gyvūną, rūšį ar priežastį, susieti su profiliais.","alt":"Mirtingumo įrašai pagal rūšis, su skaičiais pagal lytį"},{"title":"Išplėstinė paieška ir filtrai","desc":"Ieškokite pagal rūšį, priežastį, vietą, datą ar raktinį žodį.","alt":"Mirtingumo suvestinė su paryškintais laukais Visi duomenys, Visos vietos, paieška ir filtro piktograma"},{"title":"Nugaišusių gyvūnų įrašai","desc":"Visa gaišimo informacija: priežastis, ID, aptvaras, vieta, lytis.","alt":"Mirtingumo suvestinė su paryškinta pirmąja gyvūno kortele"},{"title":"Įrašų redagavimas","desc":"Redaguokite gaištamumo ataskaitas po įvedimo, kad jos būtų tikslios.","alt":"Mirtingumo ataskaita su paryškinta redagavimo pieštuko piktograma"},{"title":"Įrašų atšaukimas","desc":"Atšaukite klaidingus įrašus, kad būtų atkurta aktyvi būsena.","alt":"Mirtingumo ataskaita su paryškintu mygtuku Atšaukti mirtingumą"},{"title":"Gaišenų perkėlimas","desc":"Peržiūrėkite ir sekite gaišenų judėjimą tarp vietų.","alt":"Gaišenų perkėlimų sąrašas: 3 laukia, 1 kelyje, 8 baigti"}],"shots":{"assets/shots/p27-mortality-4.jpg":"Gaištamumo įrašo kortelė – redagavimas ir atšaukimas"}},"necropsy":{"title":"Skrodimas","intro":"Skrodimo modulis dokumentuoja pomirtinius tyrimus su išsamiais stebėjimais, organų radiniais ir medicininėmis išvadomis. Jis padeda tiksliai nustatyti gaišimo priežastį, standartizuoja ataskaitas, užtikrina savalaikį gaišenų tvarkymą ir atitinka teisės, audito bei veterinarijos standartus.","summary":"Pomirtinių tyrimų dokumentavimas su išsamiais stebėjimais, organų radiniais ir medicininėmis išvadomis","features":[{"title":"Paieška ir filtrai","desc":"Ieškokite pagal gyvūną ar rūšį; filtruokite pagal vietą, datą, prioritetą.","alt":"Skrodimų sąrašas: Gaunami, Laukiantys, Juodraštis, Baigti, su paryškintais skirtukais Pagal gyvūnus/Pagal rūšis ir paieškos juosta"},{"title":"Būsenos sekimas","desc":"Stebėkite perkėlimo etapus: atvykstantys, laukiantys, juodraščiai ir baigti.","alt":"Skrodimų sąrašas su būsenų skirtukais Gaunami, Laukiantys, Juodraštis, Baigti, pasirinkta Laukiantys"},{"title":"Gyvūno kortelė ir užklausos informacija","desc":"AID, rūšis, vieta, priežastis, užklausos pateikėjas, prioritetas.","alt":"Skrodimų sąrašas su paryškinta pirmąja prašymo kortele"},{"title":"Gaišenų perkėlimas","desc":"Peržiūrėkite perkėlimo užklausas: laukia priėmimo, gauta.","alt":"Gaišenų perkėlimai: skirtukai Laukia priėmimo ir Gauti, su prašymų kortelėmis"},{"title":"Išsamus užklausos rodinys","desc":"Peržiūrėkite visą skrodimo užklausą su gyvūno ir gaišimo informacija (priežastis, gaišenos būklė, pastabos), atnaujinkite įrašus, išsaugokite juodraštį arba pateikite užbaigę.","alt":"Skrodimo prašymo informacija: mirtingumo ataskaita, įtariama priežastis, gaišenos būklė ir būsena Laukia"},{"title":"Ataskaitos atsisiuntimas","desc":"Eksportuokite ataskaitas ar juodraščius PDF formatu įrašams ar naudojimui neprisijungus.","alt":"Skrodimo ataskaita NPS29-00033 su paryškinta atsisiuntimo piktograma, gaišenos tinkamumas ir informacija"},{"title":"Laiko juosta","desc":"Kiekvienas veiksmas sekamas su naudotoju ir laiko žyma.","alt":"Istorija: Skrodimas baigtas, Juodraštis atmestas, Išsaugota kaip juodraštis, kiekvienas su naudotoju ir laiku"}]},"fetal-death":{"title":"Vaisiaus žūtis","intro":"Vaisiaus žūties modulis registruoja ir tvarko vaisiaus žūties atvejus aptvaruose, fiksuodamas priežastį, laiką ir susijusių gyvūnų informaciją. Jis padeda veterinarinei priežiūrai, reprodukcinės sveikatos stebėsenai, tendencijų analizei ir geresniam populiacijos valdymui.","summary":"Vaisiaus žūties atvejų aptvaruose registravimas ir tvarkymas","features":[{"title":"Vaisiaus žūties įrašo pridėjimas","desc":"Registruokite naujus atvejus: priežastį, laiką, tėvus, gyvūno informaciją.","alt":"Vaisiaus žūties pridėjimo forma su aptvaru, rūšimi, tėvu ar motina"},{"title":"Paieška ir filtrai","desc":"Ieškokite pagal raktinį žodį; filtruokite pagal vietą, datą, negyvagimį ar abortą, rūšį arba lytį.","alt":"Vaisiaus žūčių sąrašas su paieška ir filtru"},{"title":"Žuvusiųjų įrašų peržiūra","desc":"Visa informacija: dienos nuo žūties, priežastis, ID, aptvaras, vieta, lytis.","alt":"Vaisiaus žūčių įrašų sąrašas, skirtukas „Still Birth“"},{"title":"Gyvūno kortelės rodinys","desc":"FID, rūšis, radimas, tėvai, vieta, lytis, pranešėjas.","alt":"Vaisiaus žūties suvestinės kortelė"},{"title":"Įrašo redagavimas","desc":"Keiskite esamą įrašą iš suvestinės, su audito seka.","alt":"Vaisiaus žūties suvestinė su redagavimo pieštuku"},{"title":"Įrašo šalinimas","desc":"Prireikus pašalinkite įrašą, išsaugant visą audito seką.","alt":"Vaisiaus žūties suvestinė su parinktimi „Delete Fetal Death“"}]},"egg-management-app":{"title":"Kiaušinių valdymas — App","intro":"Kiaušinių modulis seka visą kiaušinių gyvavimo ciklą – nuo padėjimo iki išsiritimo ar perkėlimo į inkubatorinę, užtikrindamas tikslius įrašus, atnaujinimus realiuoju laiku ir visišką atsekamumą, kad lizdų, inkubatorinės ir perykos komandos geriau koordinuotų darbą ir būtų atskaitingos.","summary":"Viso kiaušinių gyvavimo ciklo sekimas","features":[{"title":"Kiaušinių suvestinė","desc":"Skaičiai realiuoju laiku: lizduose, perkelti į inkubatorinę, pažymėti išmesti.","alt":"Kiaušinių rinkimo suvestinė: 66 lizde, 76 į inkubatorinę, 35 išmesti"},{"title":"Kiaušinių įvedimas (lizdas / inkubatorinė)","desc":"Pridėkite kiaušinius su tėvais, būkle, datomis, rūšimi, pastabomis ir priedais.","alt":"Kiaušinių pridėjimo forma su aptvaru, kilme ir kiaušinio vieta"},{"title":"Gyvavimo ciklo sekimas","desc":"Būsena, svoris ir visa kiaušinio kelio laiko juosta.","alt":"Kiaušinio kelio laiko juosta: išsirito, natūrali inkubacija"},{"title":"Natūrali inkubacija","desc":"Lizduose perimi kiaušiniai: ID, surinkimo data, būklė.","alt":"Kiaušinių lizde sąrašas su povų patelių įrašais"},{"title":"Dirbtinė inkubacija","desc":"Inkubatorinės kiaušiniai: įvertinkite, perkelkite į inkubatorių, išmeskite ar pažymėkite išsiritusius.","alt":"Kiaušinių į inkubatorinę sąrašas"},{"title":"Kiaušinių perkėlimai","desc":"Sekite vietą, etapą, išsiritimo datą, rūšį, ID ir lytį.","alt":"Perkelti kiaušiniai – partijos perkėlimo užklausos"},{"title":"Kiaušinių išmetimas","desc":"Išmeskite negyvybingus kiaušinius, užregistruodami priežastį, su audito seka.","alt":"Išmestinų kiaušinių sąrašas"},{"title":"Gyvūno ID sukūrimas","desc":"Sukurkite įrašą išsiritusiems jaunikliams, susietą su rūšimi ir tėvais.","alt":"Išsiritę kiaušiniai – „Create Animal ID“"}]},"egg-management-web":{"title":"Kiaušinių valdymas — Web","intro":"Kiaušinių valdymo žiniatinklio versija, kurią naudoja vadovai ir inkubatorinės vadovai inkubatoriams konfigūruoti, ataskaitoms rengti ir kiaušiniams sekti visuose gyvavimo ciklo etapuose. Visiškas atsekamumas, filtruojami rodiniai ir eksportuojamos ataskaitos atitikčiai ir peržiūrai.","summary":"Vadovai ir inkubatorinės vadovai konfigūruoja inkubatorius, rengia ataskaitas ir seka kiaušinius visuose gyvavimo ciklo etapuose","features":[{"title":"Inkubatorinės ir inkubatorių konfigūravimas","desc":"Nustatykite su vietomis susietas inkubatorines, kurkite patalpas, tvarkykite inkubatorius.","alt":"Inkubatorinių sąrašas su patalpomis, inkubatoriais ir vietomis"},{"title":"Ataskaitos, filtrai ir prieiga prie duomenų","desc":"Filtruokite pagal vietą, rūšį, datą ar etapą; eksportuokite ataskaitas.","alt":"Kiaušinių statistikos pagal rūšis lentelė"},{"title":"Kiaušinių sąrašas","desc":"Skirtukai pagal būseną: gauti, inkubuojami, išsiritę, išmesti, visi.","alt":"Kiaušinių sąrašas su skirtukais „Received“, „Incubation“, „Hatched“"}]},"announcement":{"title":"Skelbimai","intro":"Skelbimų modulis – centralizuota priemonė svarbioms naujienoms ir bendriems pranešimams skelbti komandoms ir vietoms. Jis leidžia tikslingai komunikuoti, planuoti ir interaktyviai įsitraukti, kad tinkama žinia pasiektų tinkamus žmones tinkamu laiku.","summary":"Centralizuota priemonė svarbioms naujienoms ir bendriems pranešimams skelbti komandoms ir vietoms","features":[{"title":"Skelbimų tipai","desc":"Bendrieji ir svarbūs, kiekvienas su savo matomumo taisyklėmis.","alt":"Skelbimų sąrašas su skirtukais „All“ ir „Created by me“, svarbių ir įprastų skelbimų kortelės"},{"title":"Bendras sąrašas","desc":"Visi skelbimai viename rodinyje, Jūsų skelbimai atskirti nuo kitų.","alt":"Skelbimo informacija: „Every Move Counts“ su pridėtu paveikslėliu"},{"title":"Skelbimų kūrimas","desc":"Nustatykite tipą, pavadinimą, matomumą; paskelbkite ar suplanuokite; peržiūrėkite ir pridėkite priedus.","alt":"Skelbimo informacija: „Every necropsy counts“, su kūrimo mygtuku"},{"title":"Veiksmai po paskelbimo","desc":"Redaguokite, atšaukite ar ištrinkite skelbimus. Pranešimai ir pradžios puslapis užtikrina, kad juos matytų tinkami žmonės.","alt":"Bendrojo skelbimo informacija su atvertu meniu „Edit“, „Cancel“, „Delete“"}]},"helpdesk-module":{"title":"Pagalbos tarnybos modulis","intro":"Užklausų modulis padeda zoologijos sodo darbuotojams pateikti ir sekti išteklių, priežiūros ar paslaugų užklausas, užtikrindamas atskaitomybę, greitesnį sprendimą ir geresnį skyrių koordinavimą. Jis pakeičia el. laiškus ir popierinius užklausų lapelius viena audituojama seka.","summary":"Išteklių, priežiūros ar paslaugų užklausų pateikimas ir sekimas, užtikrinant atskaitomybę, greitesnį sprendimą ir geresnį skyrių koordinavimą","features":[{"title":"Užklausų peržiūra pagal būseną","desc":"Laukiančios, patvirtintos, atmestos, atšauktos, vykdomos, užbaigtos.","alt":"Pagalbos tarnybos sąrašas su skirtukais „Pending Approval“, „Approved“, „Rejected“, „Cancelled“"},{"title":"Užklausų valdymas","desc":"Pateikite, redaguokite, atšaukite ar atmeskite užklausas su prioritetais.","alt":"Staliaus darbų užklausos informacija su tiekėju ir sąmata"},{"title":"Išlaidų valdymas","desc":"Pridėkite, redaguokite, dubliuokite ar ištrinkite kiekvienos pozicijos sąmatas.","alt":"Išlaidų išskaidymas: stogo dangos ir medienos pozicijos"},{"title":"Įvykdymas ir grąžinimas","desc":"Pažymėkite užklausas kaip įvykdytas arba grąžinkite jas į vykdomų būseną.","alt":"Užbaigta užklausa su parinktimi „Move Back To In-Progress“"}]},"security":{"title":"Apsauga","intro":"Apsaugos modulis valdo konkrečių vietų leidimus ir prižiūri kiaušinių perkėlimo bei išmetimo procesus ir bet kokį gyvūnų ar ligoninės perkėlimą, kad judėjimas būtų kontroliuojamas ir būtų visiškai aišku, kas, ką ir kada tvarkė.","summary":"Konkrečių vietų leidimų valdymas ir kiaušinių perkėlimo bei išmetimo, gyvūnų ir ligoninės perkėlimų priežiūra, kad būtų aišku, kas, ką ir kada tvarkė","features":[{"title":"Filtravimo funkcija","desc":"Filtruokite įrašus pagal būseną – „Show All“, „Checkout Pending“ arba „Security Checkout Cleared“ – tikslingai peržiūrai.","alt":"Filtravimo langas: „Show All“, „Checkout Pending“, „Security Checkout Cleared“"},{"title":"Įregistravimas ir išregistravimas","desc":"Įgaliota apsauga atlieka kiaušinių, gyvūnų ir ligoninės perkėlimų įregistravimą ir išregistravimą.","alt":"Perkėlimas INT-02997 su mygtuku „Security Checkout“"}]},"reports-app":{"title":"Ataskaitos - App","intro":"Ataskaitų modulis pateikia pagal kategorijas suskirstytus duomenis apie pagrindinius gyvūnų įvykius, sugrupuotus pagal konkrečias antraštes, kad greitai gautumėte įžvalgų ir galėtumėte analizuoti bet kur.","summary":"Pagal kategorijas suskirstyti duomenys apie pagrindinius gyvūnų įvykius greitoms įžvalgoms ir analizei bet kur","features":[{"title":"Filtrai","desc":"Tikslinkite ataskaitas pagal datą, vietą ar rūšį.","alt":"Pagrindinių įžvalgų ataskaita: dienos / savaitės / mėnesio filtras, data, gimstamumas ir išskaidymas pagal rūšis"},{"title":"Statistika","desc":"Filtravimas pagal datą ir statistika pagal kategorijas: gimstamumas, gaištamumas, nauji atvykėliai, perkėlimai tarp vietų (atvykę / išvykę), išoriniai, vidiniai perkėlimai ir pašaro švaistymas.","alt":"Statistikos kategorijų parinkiklis: gimstamumas, gaištamumas, nauji atvykėliai, perkėlimai tarp vietų, išorinis perkėlimas"}]},"reports-web":{"title":"Ataskaitos (Web)","intro":"Žiniatinklio versija rengia aiškias, atsisiunčiamas ataskaitas apie gyvūnų duomenis ir veiklą – gimimus, gaišimus, perkėlimus ir vertinimus – remdamasi tais pačiais įrašais kaip programėlė.","summary":"Aiškios, atsisiunčiamos ataskaitos apie gyvūnų duomenis ir veiklą","features":[{"title":"Filtrai ir paieška","desc":"Tikslinkite ataskaitas pagal datą, vietą ar rūšį.","alt":"Bendroji rūšių ataskaita: „Download report“, vietos pasirinkimas ir filtrų rodymas / slėpimas bei rūšių lentelė su patinų, patelių, nenustatytos ir neapibrėžtos lyties skaičiais"},{"title":"Atsisiunčiamos ataskaitos","desc":"Kurkite, peržiūrėkite ir atsisiųskite rūšių, dienos, gyvūnų sąrašo, gyvūnų vertinimo, gyvūnų prižiūrėtojų, naudotojų, stebėjimų, prižiūrėtojo dienoraščio, biologo dienoraščio ir aptvarų skaičiaus ataskaitas atitikčiai ir naudojimui neprisijungus.","alt":"Bendroji rūšių ataskaita: „Download report“, vietos pasirinkimas ir filtrų rodymas / slėpimas bei rūšių lentelė su patinų, patelių, nenustatytos ir neapibrėžtos lyties skaičiais"}]},"lab":{"title":"Laboratorija","intro":"Laboratorijos modulis sutelkia diagnostinių tyrimų įrašus ir rezultatus, supaprastina veterinarų ir laboratorijų darbo eigas, padeda anksti nustatyti ir gydyti ligas bei palaiko saugią skaitmeninę saugyklą biologinei saugai, auditams ir analitikai.","summary":"Diagnostinių tyrimų įrašai ir rezultatai vienoje vietoje, sklandesnis veterinarų ir laboratorijų darbas, ankstyvas ligų nustatymas ir saugi skaitmeninė saugykla biologinei saugai, auditams ir analitikai","features":[{"title":"Užklausų sąrašas ir filtravimas","desc":"Peržiūrėkite ir filtruokite laboratorines užklausas pagal laboratoriją, paiešką ar būseną – laukiančios, vykdomos, užbaigtos – su spalvomis pažymėtomis piktogramomis.","alt":"Mokslininkas dirba su mikroskopu."},{"title":"Išsamus užklausos rodinys","desc":"Matykite užklausos pateikėją, gyvūną, vietą ir susietą medicininį įrašą; atnaujinkite būseną realiuoju laiku su automatiniu sinchronizavimu tarp modulių.","alt":""},{"title":"Vieta ir prieigos kontrolė","desc":"Žymėkite laboratorijas pagal vietą; valdykite, kas gali konfigūruoti ar peržiūrėti laboratorijų duomenis.","alt":""},{"title":"Tyrimų susiejimas vietos lygiu","desc":"Priskirkite laboratorijas konkretiems diagnostiniams tyrimams tiesiai vietos skirtuke „Config“.","alt":""},{"title":"Pavienis ir masinis priskyrimas","desc":"Susiekite laboratorijas su kiekvienu tyrimu arba vienu spustelėjimu priskirkite visus tyrimus numatytajai laboratorijai.","alt":""},{"title":"Tyrimų ir mėginių valdymas","desc":"Kurkite ir tvarkykite laboratorinius tyrimus, jų dalis ir mėginių tipus (serumas, smegenų skystis ir kt.) ir susiekite juos su tinkamomis laboratorijomis.","alt":""},{"title":"Laboratorinės būsenos atnaujinimas","desc":"Sekite etapus: laukiama mėginio → mėginys gautas / atmestas / sukrešėjęs / hemolizuotas / nepakankamas → vykdoma → užbaigta (teigiamas / neigiamas / aptikta / neaptikta / neaiškus).","alt":""},{"title":"Laboratorijos perskyrimas","desc":"Prireikus perkelkite tyrimus į kitas laboratorijas netrikdydami darbo eigos.","alt":""}]},"diet":{"title":"Mityba","intro":"Mitybos modulis – centralizuota platforma efektyviam gyvūnų racionų planavimui ir valdymui. Jis leidžia mitybos komandoms kurti struktūruotus racionų planus iš konfigūruojamų komponentų, ingredientų, pašarų tipų, receptų ir derinių bei planuoti šėrimus pagal laiką, dieną ar gyvenimo etapą.","summary":"Centralizuota platforma efektyviam gyvūnų racionų planavimui ir valdymui","features":[{"title":"Racionų konfigūravimas","desc":"Kurkite racionus iš pašarų tipų, produktų, receptų ir mišinių; planuokite šėrimus pagal laiką, dieną ar gyvenimo etapą; priskirkite pagal rūšį ar atskiram gyvūnui; aktyvinkite, kopijuokite ar priskirkite racionus; pridėkite nuorodas.","alt":"Šviežių vaisių asortimentas, paruoštas gyvūnų pašarui."},{"title":"Paruošimo būdai ir supjaustymo dydis","desc":"Kurkite ir tvarkykite produktų, receptų ir derinių paruošimo būdus, kad mitybinė vertė ir tekstūra būtų vienodos.","alt":""},{"title":"Pašarų tipai","desc":"Centralizuotas, paieškai pritaikytas pašarų kategorijų sąrašas nuosekliam racionų planavimui.","alt":""},{"title":"Produktai","desc":"Pridėkite, redaguokite ir šalinkite racionų komponentus su išsamiais aprašymais ir paveikslėliais.","alt":""},{"title":"Receptai ir mišiniai","desc":"Kelių ingredientų receptai ir mišiniai: receptai pagal konkrečius kiekius, mišiniai pagal produktų procentinę dalį, su pakartotinai naudojamais komponentais ir visais veiklos žurnalais.","alt":""},{"title":"Šėrimo grupės","desc":"Grupuokite aptvarus koordinuotiems šėrimo grafikams ir racionų priskyrimui, su filtrais pagal vietą, sekciją ir rūšį.","alt":""}]},"pharmacy-app":{"title":"Vaistinė (App)","intro":"Leidžia greitai, tiksliai ir atsekamai išduoti medicinos produktus tiesiogiai įgaliotiems gydytojams, užtikrinant savalaikį įvykdymą ir automatinį atsargų atnaujinimą.","summary":"Greitas, tikslus ir atsekamas medicinos produktų išdavimas tiesiogiai įgaliotiems gydytojams","features":[{"title":"Užklausos programėlėje","desc":"Leidžia naudotojams užsisakyti produktų iš vaistinės tiesiai per programėlę.","alt":"Išdavimų sąrašas: 11 išdavimų su užklausų ID, vaistine, data, užklausos pateikėju, vaistu ir bendru kiekiu bei mygtukas „New Dispense“"},{"title":"Išdavimas programėlėje","desc":"Leidžia sandėliams išduoti produktus iš vaistinės tiesiai per programėlę.","alt":"Išdavimo DIS279 informacija: Local Pharmacy, išduota Antz Admin, vienas vaistas Crocin, bendras kiekis 100"}]},"pharmacy-web":{"title":"Vaistinė (Web)","intro":"Leidžia greitai, tiksliai ir atsekamai išduoti medicinos produktus tiesiogiai įgaliotiems gydytojams, užtikrinant savalaikį įvykdymą ir automatinį atsargų atnaujinimą nuo recepto iki lentynos, su serijų lygio matomumu ir galiojimo pabaigos sekimu visame procese.","summary":"Greitas, tikslus ir atsekamas medicinos produktų išdavimas tiesiogiai įgaliotiems gydytojams","features":[{"title":"Suvestinė","desc":"Įžvalgos realiuoju laiku apie atsargų problemas, siuntas, pirkimus, užklausas, suvartojimą, galiojimo pabaigą ir greitai judančius produktus, su vaizdinėmis tendencijomis greitiems veiksmams.","alt":"Vaistininkas tvarko vaistų lentynas."},{"title":"Išmanioji paieška ir filtrai","desc":"Greitai raskite įrašus pagal užklausos ID, gydytojo vardą ar vaistinę.","alt":""},{"title":"Pagrindiniai duomenys (stelažai ir lentynos)","desc":"Tvarkykite saugojimą pagal stelažų ir lentynų skaičių greitai prieigai ir atnaujinimams, su pritaikomais duomenimis (pakuotės, matavimo vienetai, druskos, vairuotojai, gamintojai).","alt":""},{"title":"Atsargų ataskaitų valdymas","desc":"Atsargos pagal serijas su verte ir galiojimo pabaiga; žymėkite mažų atsargų ar pasibaigusio galiojimo prekes; stebėkite artėjančias galiojimo pabaigas; tvarkykite depozitą su ginčų sprendimu.","alt":""},{"title":"Produktų ir atsargų valdymas","desc":"Kurkite produktus, sekite atsargas ir galiojimą, registruokite pirkimus ir išsiuntimus, tvarkykite bendrą registrą, valdykite pakaitalus ir variantus.","alt":""},{"title":"Išdavimo valdymas","desc":"Gydytojai gali išrašyti ir išduoti vaistus arba atsiimti juos tiesiai iš vaistinės – viskas registruojama.","alt":""},{"title":"Siuntų valdymas","desc":"Sekite gaunamas ir išsiunčiamas vaistų siuntas ir įvykdykite jas programėlėje.","alt":""},{"title":"Atsargų koregavimas ir ataskaitos","desc":"Registruokite atsargų pokyčius (trūkstamos, sugadintos, pasibaigusio galiojimo); saugokite audito istoriją; tvarkykite grąžinimus tiekėjams; atsisiųskite suvartojimo, grąžinimų, pirkimų ir išdavimo ataskaitas finansams ir poreikiui planuoti.","alt":""}]},"compliance":{"title":"Atitiktis","intro":"Atitikties modulis programėlėje pateikia organizacijos lygio gyvūnų valdymo vaizdą keliose prieglaudose, fonduose ir organizacijose ir leidžia naudotojams pasiekti eksporto, importo, siuntų ir rūšių įrašus, todėl visi reguliavimo dokumentai saugomi vienoje patikimoje, atsisiunčiamoje vietoje.","summary":"Organizacijos lygio gyvūnų valdymo vaizdas keliose prieglaudose, fonduose ir organizacijose bei prieiga prie eksporto, importo, siuntų ir rūšių įrašų programėlėje","features":[{"title":"Organizacijų apžvalga","desc":"Visos sistemoje registruotos organizacijos viename rodinyje.","alt":"Gamtosaugos teritorija su keliais objektais."},{"title":"Rūšių ir gyvūnų skaičiai","desc":"Kiekvienai organizacijai priklausančių rūšių ir visų gyvūnų skaičius.","alt":""},{"title":"Vietų aprėptis","desc":"Vietų, kuriose laikomi kiekvienos organizacijos gyvūnai, skaičius.","alt":""},{"title":"Skaidrumas ir atskaitomybė","desc":"Tikslios ataskaitos ir gyvūnų populiacijų matomumas visose organizacijose.","alt":""},{"title":"Filtrai ir atsisiuntimas","desc":"Filtruokite ir atsisiųskite dokumentus pagal pasirinktą laikotarpį.","alt":""},{"title":"Eksportas ir importas","desc":"Įrašykite ir redaguokite leidimų formas gyvūnams, eksportuojamiems į kitą šalį ar įstaigą arba importuojamiems iš jų.","alt":""},{"title":"Siuntos","desc":"Sekite siuntos informaciją, transporto būdą, siuntimo datą, konteinerius ir logistiką.","alt":""},{"title":"Rūšys","desc":"Peržiūrėkite ir atsisiųskite informaciją apie sandoryje dalyvaujančias rūšis (paukščius, žinduolius, roplius).","alt":""},{"title":"Pagrindinė konfigūracija","desc":"Nustatykite dokumentų tipus ir tvarkykite importuotojų bei eksportuotojų sąrašus eksporto ir importo įrašams.","alt":""}]}}};
